 function switchPage(pageId){const pages = document.querySelectorAll('.page');pages.forEach(page =>{page.classList.add('fadeOut');setTimeout(()=>{page.classList.remove('active','fadeOut');},300);});const targetPage = document.getElementById(pageId);if(targetPage){setTimeout(()=>{targetPage.classList.add('active','fadeIn');},300);}const navItems = document.querySelectorAll('.nav-item');navItems.forEach(item =>{item.classList.remove('active');});const correspondingNavItem = document.querySelector(`[onclick="switchPage('${pageId}')"]`);if(correspondingNavItem){correspondingNavItem.classList.add('active');}if(pageId === 'publish-post'){}}window.addEventListener('DOMContentLoaded',()=>{switchPage('home');bindSearchFunctionality();bindPublishFunctionality();bindAIChatFunctionality();bindMemberFunctionality();bindProfileFunctionality();addMicroInteractions();});function bindSearchFunctionality(){const searchInput = document.querySelector('.search-bar input');if(searchInput){searchInput.addEventListener('keypress',(e)=>{if(e.key === 'Enter'){const searchTerm = e.target.value.trim();if(searchTerm){alert(`搜索内容:${searchTerm}`);}}});}}function bindPublishFunctionality(){const titleInput = document.querySelector('#publish-post .title-input input');const charCount = document.querySelector('#publish-post .char-count');if(titleInput && charCount){titleInput.addEventListener('input',(e)=>{const length = e.target.value.length;charCount.textContent = `${length}/30`;checkPublishButtonStatus();});}const contentTextarea = document.querySelector('#publish-post .content-area textarea');if(contentTextarea){contentTextarea.addEventListener('input',checkPublishButtonStatus);}const tagsInput = document.querySelector('#publish-post .tags-section input');const tagsList = document.querySelector('#publish-post .tags-list');if(tagsInput && tagsList){tagsInput.addEventListener('keypress',(e)=>{if(e.key === 'Enter'){e.preventDefault();const tagText = e.target.value.trim();if(tagText && tagText.startsWith('#')){addTag(tagText);e.target.value = '';}}});}const settingsHeader = document.querySelector('.publish-settings .settings-header');const settingsContent = document.querySelector('.publish-settings .settings-content');const settingsToggle = document.querySelector('.publish-settings .settings-toggle');if(settingsHeader && settingsContent && settingsToggle){settingsHeader.addEventListener('click',()=>{settingsContent.classList.toggle('hidden');settingsToggle.classList.toggle('fa-chevron-down');settingsToggle.classList.toggle('fa-chevron-up');});}}function addTag(tagText){const tagsList = document.querySelector('#publish-post .tags-list');if(!tagsList)return;const existingTags = Array.from(tagsList.querySelectorAll('.tag-item span'));if(existingTags.some(tag => tag.textContent === tagText)){return;}const tagItem = document.createElement('div');tagItem.className = 'tag-item';tagItem.innerHTML = ` <span>${tagText}</span> <i class="fas fa-times remove-tag"></i> `;const removeButton = tagItem.querySelector('.remove-tag');removeButton.addEventListener('click',()=>{tagsList.removeChild(tagItem);});tagsList.appendChild(tagItem);}function checkPublishButtonStatus(){const titleInput = document.querySelector('#publish-post .title-input input');const contentTextarea = document.querySelector('#publish-post .content-area textarea');const publishBtn = document.querySelector('#publish-post .publish-btn');const finalPublishBtn = document.querySelector('#publish-post .final-publish-btn');if(titleInput && contentTextarea && publishBtn && finalPublishBtn){const isTitleValid = titleInput.value.trim().length > 0;const isContentValid = contentTextarea.value.trim().length > 0;if(isTitleValid && isContentValid){publishBtn.disabled = false;finalPublishBtn.disabled = false;}else{publishBtn.disabled = true;finalPublishBtn.disabled = true;}}}function bindAIChatFunctionality(){const sendBtn = document.querySelector('#ai-chat .send-btn');const chatInput = document.querySelector('#ai-chat .input-wrapper input');const chatMessages = document.querySelector('#ai-chat .chat-messages');const quickBtns = document.querySelectorAll('#ai-chat .quick-btn');if(sendBtn && chatInput && chatMessages){sendBtn.addEventListener('click',sendMessage);chatInput.addEventListener('keypress',(e)=>{if(e.key === 'Enter'){sendMessage();}});}quickBtns.forEach(btn =>{btn.addEventListener('click',(e)=>{chatInput.value = e.target.textContent;sendMessage();});});const switchStyleBtn = document.querySelector('#ai-chat .switch-style-btn');if(switchStyleBtn){switchStyleBtn.addEventListener('click',()=>{alert('切换AI风格功能');});}}function sendMessage(){const chatInput = document.querySelector('#ai-chat .input-wrapper input');const chatMessages = document.querySelector('#ai-chat .chat-messages');if(!chatInput || !chatMessages)return;const messageText = chatInput.value.trim();if(!messageText)return;const userMessage = createMessageElement(messageText,'user');chatMessages.appendChild(userMessage);chatInput.value = '';chatMessages.scrollTop = chatMessages.scrollHeight;setTimeout(()=>{const aiResponse = getAIResponse(messageText);const aiMessage = createMessageElement(aiResponse,'ai');chatMessages.appendChild(aiMessage);chatMessages.scrollTop = chatMessages.scrollHeight;},1000);}function createMessageElement(text,type){const messageDiv = document.createElement('div');messageDiv.className = `message ${type}-message`;messageDiv.innerHTML = ` <div class="message-content"> <p>${text}</p> </div> `;return messageDiv;}function getAIResponse(userMessage){const responses =["感谢您的提问！我正在思考这个问题...","这是一个很好的问题！让我为您解答。","根据我的分析，您可能需要了解以下信息...","我理解您的需求，让我为您提供帮助。","这个问题很有趣，让我深入思考一下..."];return responses[Math.floor(Math.random()* responses.length)];}function bindMemberFunctionality(){const packageCards = document.querySelectorAll('.package-card');const selectBtns = document.querySelectorAll('.select-package-btn');packageCards.forEach(card =>{card.addEventListener('click',()=>{packageCards.forEach(c => c.classList.remove('selected'));card.classList.add('selected');});});selectBtns.forEach(btn =>{btn.addEventListener('click',(e)=>{e.stopPropagation();const packageCard = btn.closest('.package-card');packageCards.forEach(c => c.classList.remove('selected'));packageCard.classList.add('selected');const packageName = packageCard.querySelector('.package-header h3').textContent;alert(`选择了${packageName}`);});});const paymentOptions = document.querySelectorAll('.payment-option');paymentOptions.forEach(option =>{option.addEventListener('click',()=>{paymentOptions.forEach(opt => opt.classList.remove('selected'));option.classList.add('selected');});});const autoRenewToggle = document.querySelector('#auto-renew');if(autoRenewToggle){autoRenewToggle.addEventListener('change',(e)=>{const isChecked = e.target.checked;alert(`自动续费已${isChecked ? '开启':'关闭'}`);});}}function bindProfileFunctionality(){const editAvatarBtn = document.querySelector('.edit-avatar-btn');if(editAvatarBtn){editAvatarBtn.addEventListener('click',()=>{alert('更换头像功能');});}const infoItems = document.querySelectorAll('.info-item');infoItems.forEach(item =>{item.addEventListener('click',()=>{const text = item.querySelector('span').textContent;alert(`${text}功能`);});});const securityItems = document.querySelectorAll('.security-item');securityItems.forEach(item =>{item.addEventListener('click',()=>{const text = item.querySelector('span').textContent;if(text === '注销账号'){if(confirm('确定要注销账号吗？此操作不可恢复。')){alert('账号注销功能');}}else{alert(`${text}功能`);}});});const toggleSwitches = document.querySelectorAll('.toggle-switch input');toggleSwitches.forEach(toggleSwitch =>{toggleSwitch.addEventListener('change',(e)=>{const permission = e.target.id.replace('-permission','');const isChecked = e.target.checked;console.log(`${permission}权限已${isChecked ? '开启':'关闭'}`);});});const privacyItems = document.querySelectorAll('.privacy-item span');privacyItems.forEach(item =>{if(item.textContent === '隐私协议' || item.textContent === '用户协议'){item.parentElement.addEventListener('click',()=>{alert(`${item.textContent}查看功能`);});}});}function addMicroInteractions(){const buttons = document.querySelectorAll('button,.nav-item,.function-item,.recipe-card,.kanban-card,.post-card,.info-item,.security-item,.privacy-item');buttons.forEach(button =>{button.addEventListener('mouseenter',()=>{button.style.transform = 'translateY(-2px)';button.style.transition = 'transform 0.2s ease';});button.addEventListener('mouseleave',()=>{button.style.transform = 'translateY(0)';});button.addEventListener('click',(e)=>{if(e.target.tagName === 'A' || e.target.hasAttribute('href')|| e.target.closest('.publish-icon')){return;}button.style.transform = 'scale(0.95)';setTimeout(()=>{button.style.transform = 'scale(1)';},100);});});const banner = document.querySelector('.festival-banner');if(banner){window.addEventListener('scroll',()=>{const scrollPosition = window.scrollY;banner.style.backgroundPositionY = `${scrollPosition * 0.5}px`;});}const searchInput = document.querySelector('.search-bar input');if(searchInput){searchInput.addEventListener('focus',()=>{searchInput.parentElement.style.boxShadow = '0 0 0 3px rgba(52,152,219,0.1)';});searchInput.addEventListener('blur',()=>{searchInput.parentElement.style.boxShadow = 'none';});}const inputs = document.querySelectorAll('input,textarea');inputs.forEach(input =>{input.addEventListener('focus',()=>{input.parentElement.style.boxShadow = '0 0 0 3px rgba(52,152,219,0.1)';});input.addEventListener('blur',()=>{input.parentElement.style.boxShadow = 'none';});});const cards = document.querySelectorAll('.recipe-card,.kanban-card,.post-card');cards.forEach(card =>{card.addEventListener('mouseenter',()=>{card.style.boxShadow = '0 8px 16px rgba(0,0,0,0.1)';card.style.transition = 'box-shadow 0.3s ease,transform 0.3s ease';});card.addEventListener('mouseleave',()=>{card.style.boxShadow = '0 2px 8px rgba(0,0,0,0.05)';});});}function simulateDataLoading(element){if(!element)return;element.innerHTML = '<div class="loading"></div>';setTimeout(()=>{element.innerHTML = '<p>加载完成！</p>';},1500);}function enablePullToRefresh(){const pages = document.querySelectorAll('.page');let startY = 0;let isRefreshing = false;pages.forEach(page =>{page.addEventListener('touchstart',(e)=>{if(page.scrollTop === 0){startY = e.touches[0].clientY;}});page.addEventListener('touchmove',(e)=>{if(page.scrollTop === 0 && !isRefreshing){const currentY = e.touches[0].clientY;const diff = currentY - startY;if(diff > 50){e.preventDefault();console.log('下拉刷新...');}}});page.addEventListener('touchend',(e)=>{if(page.scrollTop === 0 && !isRefreshing){const currentY = e.changedTouches[0].clientY;const diff = currentY - startY;if(diff > 100){isRefreshing = true;console.log('执行刷新...');setTimeout(()=>{console.log('刷新完成');isRefreshing = false;},1500);}}});});}function enableInfiniteScroll(){const postList = document.querySelector('.post-list');if(!postList)return;let isLoading = false;window.addEventListener('scroll',()=>{if(isLoading)return;const scrollTop = window.pageYOffset || document.documentElement.scrollTop;const scrollHeight = document.documentElement.scrollHeight;const clientHeight = document.documentElement.clientHeight;if(scrollHeight - scrollTop - clientHeight < 200){loadMorePosts();}});function loadMorePosts(){isLoading = true;const loadingIndicator = document.createElement('div');loadingIndicator.className = 'loading-indicator';loadingIndicator.innerHTML = '<div class="loading"></div><p>加载更多...</p>';postList.appendChild(loadingIndicator);setTimeout(()=>{for(let i = 0;i < 2;i++){const newPost = createPostElement();postList.appendChild(newPost);}postList.removeChild(loadingIndicator);isLoading = false;},1500);}}function createPostElement(){const postDiv = document.createElement('div');postDiv.className = 'post-card';postDiv.innerHTML = ` <div class="post-header"> <div class="user-info"> <div class="user-avatar"></div> <div class="user-details"> <div class="user-name">用户${Math.floor(Math.random()* 1000)}</div> <div class="post-time">${Math.floor(Math.random()* 24)}小时前</div> </div> </div> </div> <div class="post-content"> <p>这是一条新的社区动态，分享我的生活感悟和健康经验...</p> <div class="post-image"></div> </div> <div class="post-footer"> <div class="post-stats"> <span class="like-count"><i class="fas fa-heart"></i> ${Math.floor(Math.random()* 300)}</span> <span class="comment-count"><i class="fas fa-comment"></i> ${Math.floor(Math.random()* 100)}</span> </div> <button class="view-full-btn">查看全文</button> </div> `;return postDiv;}enableInfiniteScroll();enablePullToRefresh();